  d jsonb := $json${"people":[{"name":"Ravi Kumar","role_title":"Area head · Stock House","kind":"employee","team_size":null},{"name":"A. Sharma","role_title":"Area head · Tuyere platform","kind":"employee","team_size":null},{"name":"P. Nayak","role_title":"Area head · BLT & top","kind":"employee","team_size":null},{"name":"M. Iqbal","role_title":"Hydraulics engineer","kind":"employee","team_size":null},{"name":"S. Behera","role_title":"De‑dusting engineer","kind":"employee","team_size":null},{"name":"D. Patil","role_title":"Area head · SGP","kind":"employee","team_size":null},{"name":"V. Rao","role_title":"Blower & TRT engineer","kind":"employee","team_size":null},{"name":"K. Das","role_title":"MPH & GCP engineer","kind":"employee","team_size":null},{"name":"N. Gowda","role_title":"PCI & stoves engineer","kind":"employee","team_size":null},{"name":"R. Singh","role_title":"Mechanical fitter team · 8 people","kind":"employee","team_size":8},{"name":"Vendor team A","role_title":"Belt vulcanising · 6 people","kind":"vendor_team","team_size":6},{"name":"Vendor team B","role_title":"Refractory · 12 people","kind":"vendor_team","team_size":12}],"sections":[{"name":"Tuyere Platform & Furnace","head":"A. Sharma"},{"name":"BLT & Furnace Top","head":"P. Nayak"},{"name":"Hydraulics","head":"M. Iqbal"},{"name":"Cyclone","head":"M. Iqbal"},{"name":"CH De-dusting","head":"S. Behera"},{"name":"SGP","head":"D. Patil"},{"name":"Stock House","head":"Ravi Kumar"},{"name":"Blower & TRT","head":"V. Rao"},{"name":"MPH & GCP","head":"K. Das"},{"name":"PCI, Stove & SH De-dusting","head":"N. Gowda"}],"tasks":[{"seq":1,"section":0,"work_description":"Downleg replacement TSA no 10, 17","planned_hours":12,"manpower":4,"vendor":"","responsible":"A. Sharma","status":"completed","progress":100},{"seq":2,"section":0,"work_description":"Blowpipe changing 05, 10, 14 and syngas blowpipes 34, 25, 24, 12","planned_hours":12,"manpower":6,"vendor":"Vendor team A","responsible":"A. Sharma","status":"compl