us":"completed","progress":100},{"seq":85,"section":8,"work_description":"Closed circuit DG set maintenance","planned_hours":4,"manpower":8,"vendor":"Vendor team A","responsible":"K. Das","status":"completed","progress":100},{"seq":86,"section":8,"work_description":"NRV changing, clarified water pump 1","planned_hours":6,"manpower":10,"vendor":"","responsible":"K. Das","status":"not_started","progress":0},{"seq":87,"section":8,"work_description":"Discharge valve changing, clarified water pump 1","planned_hours":6,"manpower":12,"vendor":"","responsible":"K. Das","status":"in_progress","progress":35},{"seq":88,"section":8,"work_description":"50 NB equalizing line opening, cleaning and fixing","planned_hours":3,"manpower":4,"vendor":"Vendor team A","responsible":"K. Das","status":"completed","progress":100},{"seq":89,"section":8,"work_description":"New line tapping for scrubber pump 1 (new pump installation)","planned_hours":8,"manpower":6,"vendor":"","responsible":"K. Das","status":"completed","progress":100},{"seq":90,"section":8,"work_description":"Floor concreting at GCP cooling tower area","planned_hours":12,"manpower":8,"vendor":"Vendor team B","responsible":"K. Das","status":"not_started","progress":0},{"seq":91,"section":8,"work_description":"Civil concreting for GCP cooling tower near sluice gate of cell 1","planned_hours":12,"manpower":10,"vendor":"","responsible":"K. Das","status":"completed","progress":100},{"seq":92,"section":8,"work_description":"GCP cooling tower cold well cleaning","planned_hours":8,"manpower":12,"vendor":"Vendor team A","responsible":"K. Das","status":"completed","progress":100},{"seq":93,"section":8,"work_description":"SBT tank cleaning","planned_hours":8,"manpower":4,"vendor":"","responsible":"K. Das","status":"in_progress","progress":35},{"seq":94,"section":8,"work_description":"SBT tank main line auto knife edge valve changing","planned_hours":4,"manpower":6,"vendor":"","responsible":"K. Das","status":"completed","progress":100},{"seq":95,"section":8,"work_description":"Steam line leakage arresting","planned_hours":4,"manpower":8,"vendor":"Vendor team A","responsible":null,"status":"not_started","progress":0},{"seq":96,"section":9,"work_description":"Mill 2 bag filter inspection","planned_hours":4,"manpower":12,"vendor":"","responsible":"N. Gowda","status":"completed","progress":100},{"seq":97,"section":9,"work_description":"Mill 2 PRV replacement in N2 bypass line","planned_hours":3,"manpower":4,"vendor":"Vendor team B","responsible":"N. Gowda","status":"in_progress","progress":60},{"seq":98,"section":9,"work_description":"Stove 3 combustion air flow control valve inspection","planned_hours":4,"manpower":6,"vendor":"","responsible":"N. Gowda","status":"in_progress","progress":80},{"seq":99,"section":9,"work_description":"WG, cold blast, CA shutoff and gas shutoff valve gland replacement","planned_hours":6,"manpower":8,"vendor":"Vendor team A","responsible":"N. Gowda","status":"completed","progress":100}]}$json$::jsonb;
  p jsonb; s jsonb; t jsonb; i int;
  v_people jsonb := '{}'::jsonb;
  v_sections uuid[] := '{}';
begin
  select id into v_org from organisation where name = 'Default';
  if v_org is null then insert into organisation(name) values ('Default') returning id into v_org; end if;
  select id into v_plant from plant where name = 'Main Works';
  if v_plant is null then insert into plant(organisation_id, name) values (v_org, 'Main Works') returning id into v_plant; end if;
  select id into v_bf1 from area where code = 'bf1';
  if v_bf1 is null then insert into area(plant_id, code, name, settings) values (v_plant, 'bf1', 'Blast Furnace 1', '{"retention_days":90}') returning id into v_bf1; end if;
  select id into v_sp1 from area where code = 'sp1';
  if v_sp1 is null then insert into area(plant_id, code, name, settings) values (v_plant, 'sp1', 'Sinter Plant 1', '{"retention_days":90}') returning id into v_sp1; end if;

  -- users
  for u in select * from (values ('sunita.m','Sunita Mehta'),('ravi.k','Ravi Kumar'),('anil.v','Anil Verma'),('meena.r','Meena R.')) as x(login, name) loop
    v_email := u.login || '@users.taskmonitor.local';
    select id into v_uid from auth.users where email = v_email;
    if v_uid is null then
      v_uid := gen_random_uuid();
      insert into auth.users(instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
          raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
          confirmation_token, recovery_token, email_change, email_change_token_new)
        values ('00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated', v_email,
          crypt('ChangeMe-2026!', gen_salt('bf')), now(),
          '{"provider":"email","providers":["email"]}'::jsonb,
          jsonb_build_object('login', u.login, 'display_name', u.name), now(), now(), '', '', '', '');
      insert into auth.identities(id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at)
        values (gen_random_uuid(), v_uid, v_uid::text, 'email',
          jsonb_build_object('sub', v_uid::text, 'email', v_email, 'email_verified', true), now(), now(), now());
    end if;
    insert into profiles(id, login, display_name, must_change_password) values (v_uid, u.login, u.name, true)
      on conflict (id) do nothing;
    if u.login = 'sunita.m' then v_sunita := v_uid; elsif u.login = 'ravi.k' then v_ravi := v_uid;
    elsif u.login = 'anil.v' then v_anil := v_uid; else v_meena := v_uid; end if;
  end loop;

  insert into membership(user_id, area_id, role) values
    (v_sunita, v_bf1, 'manager'), (v_ravi, v_bf1, 'field_user'), (v_anil, v_bf1, 'manager'),
    (v_anil, v_sp1, 'manager'), (v_meena, v_sp1, 'field_user')
    on conflict (user_id, area_id) do nothing;

  if exists (select 1 from task_list where area_id = v_bf1) then
    raise notice 'bf1 already has a task list; users and memberships ensured, nothing else seeded.';
    return;
  end if;

  -- workforce
  for p in select * from jsonb_array_elements(d->'people') loop
    insert into person(area_id, kind, name, role_title, team_size, vendor_name, user_id)
      values (v_bf1, (p->>'kind')::person_kind, p->>'name', p->>'role_title', (p->>'team_size')::int,
              case when p->>'kind' = 'vendor_team' then p->>'name' end,
              case when p->>'name' = 'Ravi Kumar' then v_ravi end)
      returning id into v_pid;
    v_people := v_people || jsonb_build_object(p->>'name', v_pid);
  end loop;

  -- form v1
  insert into form(area_id, name, template) values (v_bf1, 'Shutdown jobs', 'Shutdown jobs') returning id into v_form;
  insert into form_version(area_id, form_id, version, created_by, note) values (v_bf1, v_form, 1, v_sunita, 'Seed') returning id into v_fv;
  insert into form_field(area_id, form_version_id, key, label, type, required, position) values
    (v_bf1, v_fv, 'section', 'Section', 'section', true, 1),
    (v_bf1, v_fv, 'work_description', 'Work description', 'text', true, 2),
    (v_bf1, v_fv, 'planned_hours', 'Planned hours', 'number', false, 3),
    (v_bf1, v_fv, 'manpower', 'Manpower', 'number', false, 4),
    (v_bf1, v_fv, 'vendor', 'Vendor', 'text', false, 5),
    (v_bf1, v_fv, 'responsible', 'Responsible', 'person', true, 6),
    (v_bf1, v_fv, 'photo_on_completion', 'Photo on completion', 'photo', true, 7);
  update form set current_version_id = v_fv where id = v_form;

  -- list, sections, tasks
  insert into task_list(area_id, form_id, name, planned_hours, created_by) values (v_bf1, v_form, 'Blast Furnace 1 shutdown', 72, v_sunita) returning id into v_list;
  i := 0;
  for s in select * from jsonb_array_elements(d->'sections') loop
    i := i + 1;
    insert into section(area_id, task_list_id, name, position, head_person_id)
      values (v_bf1, v_list, s->>'name', i, nullif(v_people->>(s->>'head'), '')::uuid) returning id into v_pid;
    v_sections := v_sections || v_pid;
  end loop;

  for t in select * from jsonb_array_elements(d->'tasks') loop
    v_resp := nullif(v_people->>(t->>'responsible'), '')::uuid;
    v_task := task_create(v_list, v_sections[(t->>'section')::int + 1],
      jsonb_build_object('work_description', t->>'work_description', 'planned_hours', (t->>'planned_hours')::numeric,
        'manpower', (t->>'manpower')::int, 'vendor', coalesce(t->>'vendor',''), 'photo_on_completion', true),
      v_resp, 'not_started', 0::smallint, 'excel_import', null, v_sunita, 'Imported from Excel');
    if t->>'status' <> 'not_started' then
      perform task_record_update(v_task, 'status', 'in_progress', null, 'Started. Isolation and work permit confirmed.', null, null, v_ravi);
    end if;
    if t->>'status' = 'in_progress' then
      perform task_record_update(v_task, 'progress', null, (t->>'progress')::smallint,
        (t->>'progress') || '% done, ' || coalesce(t->>'responsible','the responsible person') || ' on site.', null, null, v_ravi);
    end if;
    if t->>'status' = 'completed' then
      perform task_record_update(v_task, 'voice', 'completed', 100::smallint, 'Task completed and trial taken, no abnormality. Area cleared.',
        jsonb_build_object('status','completed','progress',100,'manpower',(t->>'manpower')::int),
        jsonb_build_object('status','completed','progress',100,'manpower',(t->>'manpower')::int), v_ravi);
    end if;
  end loop;
  raise notice 'Seeded 12 people, 10 sections, 99 tasks, 4 users (password ChangeMe-2026!).';
end
$seed$;
